def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c

    if op_c == 0:
        return 'D'
    if op_d == 0:
        return 'C'

    last = op[-1]
    me_last = me[-1]

    run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == last:
            run += 1
        else:
            break

    pc_total = 0
    pd_total = 0
    pc_c = 0
    pd_c = 0

    if n >= 12:
        for i in range(n - 1):
            if me[i] == 'C':
                pc_total += 1
                if op[i + 1] == 'C':
                    pc_c += 1
            else:
                pd_total += 1
                if op[i + 1] == 'C':
                    pd_c += 1

    if pc_total > 0:
        p_after_c = pc_c / pc_total
    else:
        p_after_c = 0.5

    if pd_total > 0:
        p_after_d = pd_c / pd_total
    else:
        p_after_d = 0.5

    if last == 'D':
        hostile = op_d * 3 > n

        if run >= 2:
            if (not hostile) and me_last == 'D' and op_c * 2 >= n:
                if (n >= 3 and me[-3] == 'D') or (n >= 4 and me[-4] == 'D' and op[-3] == 'D'):
                    return 'C'
            return 'D'

        if hostile:
            return 'D'

        provoked = (me_last == 'D')
        if n >= 3 and me[-3] == 'D' and me[-2] == 'C' and op[-2] == 'C':
            provoked = True

        if provoked:
            return 'C'
        return 'D'

    if n >= 15 and pd_total >= 5 and p_after_d >= 0.8:
        if op_c * 2 >= n or (run >= 5 and op_c * 3 >= n * 2):
            return 'D'

    if n >= 3 and me[-3] == 'D' and me[-2] == 'C' and op[-3] == 'C' and op[-2] == 'C':
        if op_c * 3 >= n * 2 and op_d <= 4:
            return 'D'

    if op_c * 5 >= n * 4:
        if n >= 95 and rng.random() < 0.25:
            return 'D'
        return 'C'

    if op_d * 2 > n:
        return 'D'

    return 'C'
